const { accessSync } = await import('node:fs');
const path = process.env['IMAGE_PATH'];
if (!path) throw new Error('Missing IMAGE_PATH env var');
try { accessSync(path); } catch { throw new Error('File not accessible: '+path); }
globalThis.imagePath = path;

const mod = await import('html5-qrcode');
const Html5Qrcode = mod.Html5Qrcode || mod.default?.Html5Qrcode || mod.default;
if (!Html5Qrcode) throw new Error('Html5Qrcode class not found');
const qrCode = new Html5Qrcode('reader');
const result = await qrCode.scanFile(globalThis.imagePath, true);
globalThis.qrResult = result;
